tm_campaign=amazon-mcf-support-button-2023-12-07','actioned','',NULL,NULL),(151,51,'view_docs','Learn about Deposit schedules','https://woocommerce.com/document/woopayments/deposits/deposit-schedule/?utm_source=inbox_note&utm_medium=product&utm_campaign=view_docs#available-funds','unactioned','',NULL,NULL),(152,52,'sirt-woo-2024-11-xss-admin','See available updates','http://the-fashion-frame.local/wp-admin/update-core.php?','unactioned','',NULL,NULL),(153,52,'sirt-woo-2024-11-xss-admin','Dismiss','#','actioned','',NULL,NULL),(154,53,'paypal-braintree-sdk-depreciation-2025-02-20-button','Upgrade now','http://the-fashion-frame.local/wp-admin/wp-admin/plugins.php','actioned','',NULL,NULL),(155,54,'uk-vat-notice-button-2025-04-30','Learn more about this extension','https://wordpress.org/plugins/eu-vat-for-woocommerce/','actioned','',NULL,NULL),(156,55,'paypal-braintree-sdk-depreciation-2025-05-30-button','Update now','http://the-fashion-frame.local/wp-admin/wp-admin/plugins.php','unactioned','',NULL,NULL),(157,56,'woo-dotcom-course-2026-06-09','Visit the course','https://wordpress.com/support/courses/build-your-store-with-woocommerce/','actioned','',NULL,NULL);
